// ETFs have no insiders or analyst coverage. Insider window = 120 days back.
const ctx = $input.first().json;
const from = new Date(new Date(ctx.as_of + 'T00:00:00Z').getTime() - 120 * 86400000).toISOString().slice(0, 10);
return ctx.tickers.filter(t => !(ctx.benchmarks || []).includes(t)).map(t => ({ json: { ticker: t, run_id: ctx.run_id, from, to: ctx.as_of } }));

// Both HTTP nodes keep one item per ticker in request order. Insider rows keyed by SEC accession + transaction detail.
const ctx = $('When called').first().json;
const reqs = $('One item per ticker').all();
const ins = $('Finnhub insiders').all(), recs = $input.all();
const num = (v) => (v == null || v === '' || !isFinite(Number(v)) ? null : Number(v));
const body = (it) => { let b = it.json.body; if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } } return b; };
const code = (it) => Number(it.json.statusCode) || null;
const insiders = [], recRows = [], usage = [], seen = {}, seenRec = new Set();
reqs.forEach((rq, i) => {
  const t = rq.json.ticker;
  const a = ins[i], b = recs[i];
  const ab = a ? body(a) : null, bb = b ? body(b) : null;
  const aOk = a && code(a) === 200 && ab && Array.isArray(ab.data);
  const bOk = b && code(b) === 200 && Array.isArray(bb);
  usage.push({ ticker: t, endpoint: 'stock/insider-transactions', status: aOk ? 'ok' : (a && code(a) === 429 ? 'quota_skip' : 'error'), http_code: a ? code(a) : null });
  usage.push({ ticker: t, endpoint: 'stock/recommendation', status: bOk ? 'ok' : (b && code(b) === 429 ? 'quota_skip' : 'error'), http_code: b ? code(b) : null });
  if (aOk) for (const x of ab.data) {
    const chg = num(x.change), px = num(x.transactionPrice), c = x.transactionCode || '';
    const key = [x.id || 'na', t, (x.name || '').replace(/[^A-Za-z0-9]/g, '').slice(0, 24), x.transactionDate || '', c, chg ?? '', px ?? '', x.isDerivative ? 'd' : 'n'].join('-');
    // A filing can list the same transaction twice; number repeats so both rows survive the upsert.
    seen[key] = (seen[key] || 0) + 1;
    insiders.push({ id: 'fh-' + key + (seen[key] > 1 ? '-' + seen[key] : ''), ticker: t, filed_at: x.filingDate || null, tx_date: x.transactionDate || null, insider: x.name || null,
      tx_type: c === 'P' ? 'P' : (c === 'S' ? 'S' : 'other'), code: c || null, shares: chg == null ? null : Math.round(chg), price: px,
      value: chg != null && px != null ? Math.round(Math.abs(chg) * px * 100) / 100 : null, derivative: !!x.isDerivative });
  }
  if (bOk) for (const x of bb) if (x.period && !seenRec.has(t + x.period) && seenRec.add(t + x.period)) recRows.push({ ticker: t, as_of: x.period, strong_buy: num(x.strongBuy), buy: num(x.buy), hold: num(x.hold), sell: num(x.sell), strong_sell: num(x.strongSell) });
});
const failed = usage.filter(u => u.status !== 'ok');
const failedT = [...new Set(failed.map(u => u.ticker))];
return [{ json: { run_id: ctx.run_id, as_of: ctx.as_of, insiders, recs: recRows, usage, calls: usage.length, insider_rows: insiders.length, rec_rows: recRows.length, failed: failed.length, failed_tickers: failedT } }];
